import ast

class Add(ast.AST):
    _fields = ("left", "right")            # ast convention: all children named
    def __init__(self, left, right):
        self.left, self.right = left, right

class IntLit(ast.AST):
    _fields = ("value",)

def walk(node):
    yield node
    for child in ast.iter_child_nodes(node):   # any ast.AST subclass
        yield from walk(child)
